def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (list, tuple)):
        raise ValueError("Coordinate must be a list or tuple")
    if len(coord) != self.ndim:
        raise ValueError("Coordinate must have the same number of dimensions as the histogram")
    if not isinstance(weight, (int, float)):
        raise ValueError("Weight must be a number")
    if weight <= 0:
        raise ValueError("Weight must be positive")

    # Check if the coordinate is within the histogram edges
    if not all(self.edges[i][0] <= coord[i] <= self.edges[i][1] for i in range(self.ndim)):
        return

    # Find the bin index for the coordinate
    bin_index = tuple(self._find_bin_index(coord, i) for i in range(self.ndim))

    # Increment the bin count
    self.bins[bin_index] += weight

