def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check that fixity has a 'fixities' key
    if 'fixities' not in fixity:
        raise ValueError("Fixity block must have a 'fixities' key")

    # Check that fixities is a list
    if not isinstance(fixity['fixities'], list):
        raise ValueError("Fixities must be a list")

    # Check that each fixity is a dictionary
    for fixity_item in fixity['fixities']:
        if not isinstance(fixity_item, dict):
            raise ValueError("Each fixity must be a dictionary")

    # Check that each fixity has a 'filepath' key
    for fixity_item in fixity['fixities']:
        if 'filepath' not in fixity_item:
            raise ValueError("Each fixity must have a 'filepath' key")

    # Check that each filepath is a string
    for fixity_item in fixity['fixities']:
        if not isinstance(fixity_item['filepath'], str):
            raise ValueError("Each filepath must be a string")

    # Check that each filepath is in the manifest
    for fixity_item in fixity['fixities']:
        if fixity_item['filepath'] not in manifest_files:
            raise ValueError("Each filepath must be in the manifest")

    # Check that there are no duplicate filepaths
    filepaths = [fixity_item['filepath'] for fixity_item in fixity['fixities']]
    if len(filepaths) != len(set(filepaths)):
        raise ValueError("There are duplicate filepaths in the fixity block")

    # Check that there are no missing files in the manifest
    manifest_filepaths = [file['filepath'] for file in manifest_files]
    if len(manifest_filepaths) != len(set(manifest_filepaths)):
        raise ValueError("There are duplicate filepaths in the manifest")

    # Check that there are no missing files in the fixity block
    fixity_filepaths = [fixity_item['filepath'] for fixity_item in fixity['fixities']]
    if len(fixity_filepaths) != len(set(fixity_filepaths)):
        raise ValueError("There are duplicate filepaths in the fixity block")

