    """Render the given version pieces into the requested style."""
    # Check if the style is valid
    if style not in ['plain', 'markdown', 'html']:
        raise ValueError("Invalid style: " + style)

    # Render the pieces
    rendered_pieces = []
    for piece in pieces:
        if style == 'plain':
            rendered_pieces.append(piece.text)
        elif style == 'markdown':
