def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        raise TypeError("The candidate must be an instance of the interface class.")

    if tentative:
        return True

    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            raise TypeError("The candidate is missing the method " + method + ".")

        if not callable(getattr(candidate, method)):
            raise TypeError("The method " + method + " must be callable.")

    return True

